"""SentinelX AI - Response Decision, Approval, and Simulation Outcome Schemas

Enforces safe response selection, allowlisted actions, and deterministic human-in-the-loop approvals.
"""

from datetime import datetime
from typing import List, Optional
from pydantic import Field, field_validator
from .common import (
    ActionType,
    ApprovalStatus,
    ExecutionMode,
    SafetyResult,
    SentinelBaseModel,
    ensure_utc_datetime,
)
from .events import ID_PATTERN


class ResponseDecision(SentinelBaseModel):
    """Decision record generated by RL Policy or Rule-Based Baseline."""
    decision_id: str = Field(
        ...,
        description="Unique identifier for the decision (e.g. dec-demo-0001)"
    )
    incident_id: str = Field(
        ...,
        description="Reference to the target incident"
    )
    policy_version: str = Field(
        ...,
        min_length=1,
        max_length=64,
        description="Policy algorithm and version identifier (e.g. 'qtable-v1.0', 'baseline-rule-v1')"
    )
    proposed_action: ActionType = Field(
        ...,
        description="Candidate response action from allowlisted catalogue"
    )
    safety_result: SafetyResult = Field(
        ...,
        description="Deterministic safety validation result"
    )
    reason_codes: List[str] = Field(
        ...,
        min_length=1,
        description="Traceable categorical reason tags (e.g. ['HIGH_RISK', 'CORRELATED_EVENTS'])"
    )
    evidence_event_ids: List[str] = Field(
        ...,
        min_length=1,
        description="Event IDs providing justification for the decision"
    )
    # SAFETY INVARIANT: Only simulation is permissible!
    execution_mode: ExecutionMode = Field(
        default=ExecutionMode.SIMULATION,
        description="Mandatory execution mode (strictly 'simulation')"
    )
    created_at: datetime = Field(
        ...,
        description="Timestamp of decision generation in UTC"
    )

    @field_validator("decision_id", "incident_id")
    @classmethod
    def validate_ids(cls, value: str) -> str:
        if not ID_PATTERN.match(value):
            raise ValueError(f"Invalid identifier format '{value}'.")
        return value

    @field_validator("evidence_event_ids")
    @classmethod
    def validate_evidence_event_ids(cls, values: List[str]) -> List[str]:
        for eid in values:
            if not ID_PATTERN.match(eid):
                raise ValueError(f"Invalid event ID in decision evidence '{eid}'.")
        return values

    @field_validator("created_at")
    @classmethod
    def validate_utc(cls, value: datetime) -> datetime:
        return ensure_utc_datetime(value)


class ApprovalRecord(SentinelBaseModel):
    """Audit record for human approval workflow on high-consequence responses."""
    approval_id: str = Field(..., description="Unique approval audit identifier")
    decision_id: str = Field(..., description="Target decision identifier")
    incident_id: str = Field(..., description="Target incident identifier")
    reviewer_id: str = Field(..., min_length=2, max_length=64, description="Analyst identity")
    status: ApprovalStatus = Field(..., description="Approval status (approved, rejected, expired)")
    comment: Optional[str] = Field(default=None, max_length=500, description="Analyst reasoning or feedback")
    timestamp: datetime = Field(..., description="Timestamp of approval decision in UTC")

    @field_validator("approval_id", "decision_id", "incident_id")
    @classmethod
    def validate_ids(cls, value: str) -> str:
        if not ID_PATTERN.match(value):
            raise ValueError(f"Invalid identifier format '{value}'.")
        return value

    @field_validator("timestamp")
    @classmethod
    def validate_utc(cls, value: datetime) -> datetime:
        return ensure_utc_datetime(value)


class SimulationOutcome(SentinelBaseModel):
    """Outcome and reward feedback record from simulated execution."""
    outcome_id: str = Field(..., description="Unique outcome record identifier")
    decision_id: str = Field(..., description="Associated response decision")
    incident_id: str = Field(..., description="Associated incident")
    action: ActionType = Field(..., description="Simulated action executed")
    containment_success: bool = Field(..., description="Whether the action contained the simulated threat")
    operational_disruption_cost: float = Field(
        ...,
        ge=0.0,
        description="Simulated impact/cost on normal operational traffic"
    )
    response_delay_ms: float = Field(
        ...,
        ge=0.0,
        description="Simulated time to mitigate in milliseconds"
    )
    reward: float = Field(
        ...,
        description="Calculated scalar reward for RL policy update"
    )
    episode_id: Optional[str] = Field(default=None, description="Simulation episode identifier")
    recorded_at: datetime = Field(..., description="Outcome recording timestamp in UTC")

    @field_validator("outcome_id", "decision_id", "incident_id")
    @classmethod
    def validate_ids(cls, value: str) -> str:
        if not ID_PATTERN.match(value):
            raise ValueError(f"Invalid identifier format '{value}'.")
        return value

    @field_validator("recorded_at")
    @classmethod
    def validate_utc(cls, value: datetime) -> datetime:
        return ensure_utc_datetime(value)
